window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5c2346d903f4f65e"]={"versions": [{"id": "FIG-5c2346d903f4f65e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Zustandsdiagramm zur Veranschaulichung des Startverhaltens einer AUTOSAR-OS-Schedule-Table im Vergleich zwischen absolutem (<code>StartScheduleTableAbs</code>) und relativem (<code>StartScheduleTableRel</code>) Start auf Basis eines zugrunde liegenden OS-Counters (AUTOSAR Classic Platform, OS-Spezifikation).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schedule Table Tbl</strong>: Konfigurierte Ablauf-Tabelle mit den Parametern <code>Initial Offset = 2</code>, <code>Final Delay = 2</code> und einer Gesamtdauer von <code>Duration = 10</code>. Enthält die Verfallspunkte (Expiry Points) <code>EP1</code> (Offset 2), <code>EP2</code> (Offset 5) und <code>EP3</code> (Offset 8).</li>\n<li><strong>Zustände der Schedule Table</strong>: <code>STOPPED</code> und <code>RUNNING</code>.</li>\n<li><strong>OS Counter</strong>: 16-Bit-Zähler (Wertebereich bis 65535 mit Überlauf auf 0, 1, 2, ...).</li>\n<li><strong>API-Dienste</strong>:</li>\n<li><code>StartScheduleTableAbs(Tbl, 2)</code>: Absoluter Startaufruf bezogen auf Zählerstand 2.</li>\n<li><code>StartScheduleTableRel(Tbl, 2)</code>: Relativer Startaufruf mit einem zusätzlichen Offset von 2 Ticks ab Aufrufzeitpunkt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Definition der Schedule Table (<code>Tbl</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Basistabelle startet bei Offset 0, erreicht <code>EP1</code> bei Tick 2, <code>EP2</code> bei Tick 5, <code>EP3</code> bei Tick 8 und schließt den Durchlauf nach dem <code>Final Delay = 2</code> bei Offset 10 (Tick 0 der Folgewiederholung) ab.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Absoluter Start (<code>StartScheduleTableAbs(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt, während der OS Counter auf Stand 65535 steht. Der Zustand wechselt sofort von <code>STOPPED</code> nach <code>RUNNING</code>.</li>\n<li>Der initiale Verfallspunkt (<code>EP1</code>) wird bei Zählerstand <code>Counter = Startwert + Initial Offset = 2 + 2 = 4</code> abgearbeitet.</li>\n<li>Der Tabellenoffset 0 wird synchron zum absoluten Startwert 2 des OS Counters ausgerichtet. Entsprechend fallen <code>EP1</code> auf OS Counter 4, <code>EP2</code> auf OS Counter 7 und <code>EP3</code> auf OS Counter 10.</li>\n<li>Nach Erreichen von OS Counter 12 (Tabellendauer 10 Ticks) wiederholt sich die Tabelle periodisch: nächster Zyklus beginnt bei OS Counter 12, Folgedurchläufe schalten <code>EP1</code> bei 14, <code>EP2</code> bei 17, <code>EP3</code> bei 20 usw.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Relativer Start (<code>StartScheduleTableRel(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt ebenfalls bei OS Counter 65535, wodurch der Zustand von <code>STOPPED</code> nach <code>RUNNING</code> wechselt.</li>\n<li>Der Tabellennullpunkt wird relativ um das übergebene Offset (2 Ticks) verschoben: Tabellenoffset 0 liegt bei OS Counter <code>65535 + 2 = 1</code>.</li>\n<li>Entsprechend wird der initiale Verfallspunkt <code>EP1</code> bei OS Counter <code>1 + Initial Offset (2) = 3</code> erreicht.</li>\n<li>Nachfolgende Expiry Points liegen bei OS Counter 6 (<code>EP2</code>), 9 (<code>EP3</code>) und Tabellenende bei OS Counter 11.</li>\n<li>Die Folgeiteration startet bei OS Counter 11 mit <code>EP1</code> bei 13, <code>EP2</code> bei 16, <code>EP3</code> bei 19 etc.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der API-Aufruf <code>StartScheduleTableAbs(ScheduleTableID, Start)</code> setzt den Zustand synchron auf <code>RUNNING</code>, wobei der absolute Startwert als Referenzbasis dient.</li>\n<li>Bei <code>StartScheduleTableRel(ScheduleTableID, Offset)</code> wird die Startzeit relativ zum aktuellen Zählerstand um den Parameter <code>Offset</code> in die Zukunft verschoben.</li>\n<li>In beiden Fällen wird der erste Verfallspunkt erst nach Ablauf des in der Schedule Table konfigurierten <code>Initial Offset</code> relativ zum Aktivierungszeitpunkt der Tabelle ausgeführt.</li>\n<li>Das Diagramm demonstriert die zyklische Wiederholung periodischer Schedule Tables nach Ablauf der Gesamtdauer (<code>Duration = Summe aller Delays inkl. Final Delay</code>).</li>\n</ul>"}, {"id": "FIG-1d02e8279b6a366f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Zustandsdiagramm zur Veranschaulichung des Startverhaltens einer AUTOSAR-OS-Schedule-Table im Vergleich zwischen absolutem (<code>StartScheduleTableAbs</code>) und relativem (<code>StartScheduleTableRel</code>) Start auf Basis eines zugrunde liegenden OS-Counters (AUTOSAR Classic Platform, OS-Spezifikation).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schedule Table Tbl</strong>: Konfigurierte Ablauf-Tabelle mit den Parametern <code>Initial Offset = 2</code>, <code>Final Delay = 2</code> und einer Gesamtdauer von <code>Duration = 10</code>. Enthält die Verfallspunkte (Expiry Points) <code>EP1</code> (Offset 2), <code>EP2</code> (Offset 5) und <code>EP3</code> (Offset 8).</li>\n<li><strong>Zustände der Schedule Table</strong>: <code>STOPPED</code> und <code>RUNNING</code>.</li>\n<li><strong>OS Counter</strong>: 16-Bit-Zähler (Wertebereich bis 65535 mit Überlauf auf 0, 1, 2, ...).</li>\n<li><strong>API-Dienste</strong>:</li>\n<li><code>StartScheduleTableAbs(Tbl, 2)</code>: Absoluter Startaufruf bezogen auf Zählerstand 2.</li>\n<li><code>StartScheduleTableRel(Tbl, 2)</code>: Relativer Startaufruf mit einem zusätzlichen Offset von 2 Ticks ab Aufrufzeitpunkt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Definition der Schedule Table (<code>Tbl</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Basistabelle startet bei Offset 0, erreicht <code>EP1</code> bei Tick 2, <code>EP2</code> bei Tick 5, <code>EP3</code> bei Tick 8 und schließt den Durchlauf nach dem <code>Final Delay = 2</code> bei Offset 10 (Tick 0 der Folgewiederholung) ab.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Absoluter Start (<code>StartScheduleTableAbs(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt, während der OS Counter auf Stand 65535 steht. Der Zustand wechselt sofort von <code>STOPPED</code> nach <code>RUNNING</code>.</li>\n<li>Der initiale Verfallspunkt (<code>EP1</code>) wird bei Zählerstand <code>Counter = Startwert + Initial Offset = 2 + 2 = 4</code> abgearbeitet.</li>\n<li>Der Tabellenoffset 0 wird synchron zum absoluten Startwert 2 des OS Counters ausgerichtet. Entsprechend fallen <code>EP1</code> auf OS Counter 4, <code>EP2</code> auf OS Counter 7 und <code>EP3</code> auf OS Counter 10.</li>\n<li>Nach Erreichen von OS Counter 12 (Tabellendauer 10 Ticks) wiederholt sich die Tabelle periodisch: nächster Zyklus beginnt bei OS Counter 12, Folgedurchläufe schalten <code>EP1</code> bei 14, <code>EP2</code> bei 17, <code>EP3</code> bei 20 usw.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Relativer Start (<code>StartScheduleTableRel(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt ebenfalls bei OS Counter 65535, wodurch der Zustand von <code>STOPPED</code> nach <code>RUNNING</code> wechselt.</li>\n<li>Der Tabellennullpunkt wird relativ um das übergebene Offset (2 Ticks) verschoben: Tabellenoffset 0 liegt bei OS Counter <code>65535 + 2 = 1</code>.</li>\n<li>Entsprechend wird der initiale Verfallspunkt <code>EP1</code> bei OS Counter <code>1 + Initial Offset (2) = 3</code> erreicht.</li>\n<li>Nachfolgende Expiry Points liegen bei OS Counter 6 (<code>EP2</code>), 9 (<code>EP3</code>) und Tabellenende bei OS Counter 11.</li>\n<li>Die Folgeiteration startet bei OS Counter 11 mit <code>EP1</code> bei 13, <code>EP2</code> bei 16, <code>EP3</code> bei 19 etc.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der API-Aufruf <code>StartScheduleTableAbs(ScheduleTableID, Start)</code> setzt den Zustand synchron auf <code>RUNNING</code>, wobei der absolute Startwert als Referenzbasis dient.</li>\n<li>Bei <code>StartScheduleTableRel(ScheduleTableID, Offset)</code> wird die Startzeit relativ zum aktuellen Zählerstand um den Parameter <code>Offset</code> in die Zukunft verschoben.</li>\n<li>In beiden Fällen wird der erste Verfallspunkt erst nach Ablauf des in der Schedule Table konfigurierten <code>Initial Offset</code> relativ zum Aktivierungszeitpunkt der Tabelle ausgeführt.</li>\n<li>Das Diagramm demonstriert die zyklische Wiederholung periodischer Schedule Tables nach Ablauf der Gesamtdauer (<code>Duration = Summe aller Delays inkl. Final Delay</code>).</li>\n</ul>"}, {"id": "FIG-5f12181a416d74b7", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Zustandsdiagramm zur Veranschaulichung des Startverhaltens einer AUTOSAR-OS-Schedule-Table im Vergleich zwischen absolutem (<code>StartScheduleTableAbs</code>) und relativem (<code>StartScheduleTableRel</code>) Start auf Basis eines zugrunde liegenden OS-Counters (AUTOSAR Classic Platform, OS-Spezifikation).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schedule Table Tbl</strong>: Konfigurierte Ablauf-Tabelle mit den Parametern <code>Initial Offset = 2</code>, <code>Final Delay = 2</code> und einer Gesamtdauer von <code>Duration = 10</code>. Enthält die Verfallspunkte (Expiry Points) <code>EP1</code> (Offset 2), <code>EP2</code> (Offset 5) und <code>EP3</code> (Offset 8).</li>\n<li><strong>Zustände der Schedule Table</strong>: <code>STOPPED</code> und <code>RUNNING</code>.</li>\n<li><strong>OS Counter</strong>: 16-Bit-Zähler (Wertebereich bis 65535 mit Überlauf auf 0, 1, 2, ...).</li>\n<li><strong>API-Dienste</strong>:</li>\n<li><code>StartScheduleTableAbs(Tbl, 2)</code>: Absoluter Startaufruf bezogen auf Zählerstand 2.</li>\n<li><code>StartScheduleTableRel(Tbl, 2)</code>: Relativer Startaufruf mit einem zusätzlichen Offset von 2 Ticks ab Aufrufzeitpunkt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Definition der Schedule Table (<code>Tbl</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Basistabelle startet bei Offset 0, erreicht <code>EP1</code> bei Tick 2, <code>EP2</code> bei Tick 5, <code>EP3</code> bei Tick 8 und schließt den Durchlauf nach dem <code>Final Delay = 2</code> bei Offset 10 (Tick 0 der Folgewiederholung) ab.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Absoluter Start (<code>StartScheduleTableAbs(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt, während der OS Counter auf Stand 65535 steht. Der Zustand wechselt sofort von <code>STOPPED</code> nach <code>RUNNING</code>.</li>\n<li>Der initiale Verfallspunkt (<code>EP1</code>) wird bei Zählerstand <code>Counter = Startwert + Initial Offset = 2 + 2 = 4</code> abgearbeitet.</li>\n<li>Der Tabellenoffset 0 wird synchron zum absoluten Startwert 2 des OS Counters ausgerichtet. Entsprechend fallen <code>EP1</code> auf OS Counter 4, <code>EP2</code> auf OS Counter 7 und <code>EP3</code> auf OS Counter 10.</li>\n<li>Nach Erreichen von OS Counter 12 (Tabellendauer 10 Ticks) wiederholt sich die Tabelle periodisch: nächster Zyklus beginnt bei OS Counter 12, Folgedurchläufe schalten <code>EP1</code> bei 14, <code>EP2</code> bei 17, <code>EP3</code> bei 20 usw.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Relativer Start (<code>StartScheduleTableRel(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt ebenfalls bei OS Counter 65535, wodurch der Zustand von <code>STOPPED</code> nach <code>RUNNING</code> wechselt.</li>\n<li>Der Tabellennullpunkt wird relativ um das übergebene Offset (2 Ticks) verschoben: Tabellenoffset 0 liegt bei OS Counter <code>65535 + 2 = 1</code>.</li>\n<li>Entsprechend wird der initiale Verfallspunkt <code>EP1</code> bei OS Counter <code>1 + Initial Offset (2) = 3</code> erreicht.</li>\n<li>Nachfolgende Expiry Points liegen bei OS Counter 6 (<code>EP2</code>), 9 (<code>EP3</code>) und Tabellenende bei OS Counter 11.</li>\n<li>Die Folgeiteration startet bei OS Counter 11 mit <code>EP1</code> bei 13, <code>EP2</code> bei 16, <code>EP3</code> bei 19 etc.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der API-Aufruf <code>StartScheduleTableAbs(ScheduleTableID, Start)</code> setzt den Zustand synchron auf <code>RUNNING</code>, wobei der absolute Startwert als Referenzbasis dient.</li>\n<li>Bei <code>StartScheduleTableRel(ScheduleTableID, Offset)</code> wird die Startzeit relativ zum aktuellen Zählerstand um den Parameter <code>Offset</code> in die Zukunft verschoben.</li>\n<li>In beiden Fällen wird der erste Verfallspunkt erst nach Ablauf des in der Schedule Table konfigurierten <code>Initial Offset</code> relativ zum Aktivierungszeitpunkt der Tabelle ausgeführt.</li>\n<li>Das Diagramm demonstriert die zyklische Wiederholung periodischer Schedule Tables nach Ablauf der Gesamtdauer (<code>Duration = Summe aller Delays inkl. Final Delay</code>).</li>\n</ul>"}, {"id": "FIG-5cd76ae2c246879d", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Zustandsdiagramm zur Veranschaulichung des Startverhaltens einer AUTOSAR-OS-Schedule-Table im Vergleich zwischen absolutem (<code>StartScheduleTableAbs</code>) und relativem (<code>StartScheduleTableRel</code>) Start auf Basis eines zugrunde liegenden OS-Counters (AUTOSAR Classic Platform, OS-Spezifikation).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schedule Table Tbl</strong>: Konfigurierte Ablauf-Tabelle mit den Parametern <code>Initial Offset = 2</code>, <code>Final Delay = 2</code> und einer Gesamtdauer von <code>Duration = 10</code>. Enthält die Verfallspunkte (Expiry Points) <code>EP1</code> (Offset 2), <code>EP2</code> (Offset 5) und <code>EP3</code> (Offset 8).</li>\n<li><strong>Zustände der Schedule Table</strong>: <code>STOPPED</code> und <code>RUNNING</code>.</li>\n<li><strong>OS Counter</strong>: 16-Bit-Zähler (Wertebereich bis 65535 mit Überlauf auf 0, 1, 2, ...).</li>\n<li><strong>API-Dienste</strong>:</li>\n<li><code>StartScheduleTableAbs(Tbl, 2)</code>: Absoluter Startaufruf bezogen auf Zählerstand 2.</li>\n<li><code>StartScheduleTableRel(Tbl, 2)</code>: Relativer Startaufruf mit einem zusätzlichen Offset von 2 Ticks ab Aufrufzeitpunkt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Definition der Schedule Table (<code>Tbl</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Basistabelle startet bei Offset 0, erreicht <code>EP1</code> bei Tick 2, <code>EP2</code> bei Tick 5, <code>EP3</code> bei Tick 8 und schließt den Durchlauf nach dem <code>Final Delay = 2</code> bei Offset 10 (Tick 0 der Folgewiederholung) ab.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Absoluter Start (<code>StartScheduleTableAbs(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt, während der OS Counter auf Stand 65535 steht. Der Zustand wechselt sofort von <code>STOPPED</code> nach <code>RUNNING</code>.</li>\n<li>Der initiale Verfallspunkt (<code>EP1</code>) wird bei Zählerstand <code>Counter = Startwert + Initial Offset = 2 + 2 = 4</code> abgearbeitet.</li>\n<li>Der Tabellenoffset 0 wird synchron zum absoluten Startwert 2 des OS Counters ausgerichtet. Entsprechend fallen <code>EP1</code> auf OS Counter 4, <code>EP2</code> auf OS Counter 7 und <code>EP3</code> auf OS Counter 10.</li>\n<li>Nach Erreichen von OS Counter 12 (Tabellendauer 10 Ticks) wiederholt sich die Tabelle periodisch: nächster Zyklus beginnt bei OS Counter 12, Folgedurchläufe schalten <code>EP1</code> bei 14, <code>EP2</code> bei 17, <code>EP3</code> bei 20 usw.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Relativer Start (<code>StartScheduleTableRel(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt ebenfalls bei OS Counter 65535, wodurch der Zustand von <code>STOPPED</code> nach <code>RUNNING</code> wechselt.</li>\n<li>Der Tabellennullpunkt wird relativ um das übergebene Offset (2 Ticks) verschoben: Tabellenoffset 0 liegt bei OS Counter <code>65535 + 2 = 1</code>.</li>\n<li>Entsprechend wird der initiale Verfallspunkt <code>EP1</code> bei OS Counter <code>1 + Initial Offset (2) = 3</code> erreicht.</li>\n<li>Nachfolgende Expiry Points liegen bei OS Counter 6 (<code>EP2</code>), 9 (<code>EP3</code>) und Tabellenende bei OS Counter 11.</li>\n<li>Die Folgeiteration startet bei OS Counter 11 mit <code>EP1</code> bei 13, <code>EP2</code> bei 16, <code>EP3</code> bei 19 etc.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der API-Aufruf <code>StartScheduleTableAbs(ScheduleTableID, Start)</code> setzt den Zustand synchron auf <code>RUNNING</code>, wobei der absolute Startwert als Referenzbasis dient.</li>\n<li>Bei <code>StartScheduleTableRel(ScheduleTableID, Offset)</code> wird die Startzeit relativ zum aktuellen Zählerstand um den Parameter <code>Offset</code> in die Zukunft verschoben.</li>\n<li>In beiden Fällen wird der erste Verfallspunkt erst nach Ablauf des in der Schedule Table konfigurierten <code>Initial Offset</code> relativ zum Aktivierungszeitpunkt der Tabelle ausgeführt.</li>\n<li>Das Diagramm demonstriert die zyklische Wiederholung periodischer Schedule Tables nach Ablauf der Gesamtdauer (<code>Duration = Summe aller Delays inkl. Final Delay</code>).</li>\n</ul>"}, {"id": "FIG-da4bd3ddc9859e11", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablauf- und Zustandsdiagramm zur Veranschaulichung des Startverhaltens einer AUTOSAR-OS-Schedule-Table im Vergleich zwischen absolutem (<code>StartScheduleTableAbs</code>) und relativem (<code>StartScheduleTableRel</code>) Start auf Basis eines zugrunde liegenden OS-Counters (AUTOSAR Classic Platform, OS-Spezifikation).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Schedule Table Tbl</strong>: Konfigurierte Ablauf-Tabelle mit den Parametern <code>Initial Offset = 2</code>, <code>Final Delay = 2</code> und einer Gesamtdauer von <code>Duration = 10</code>. Enthält die Verfallspunkte (Expiry Points) <code>EP1</code> (Offset 2), <code>EP2</code> (Offset 5) und <code>EP3</code> (Offset 8).</li>\n<li><strong>Zustände der Schedule Table</strong>: <code>STOPPED</code> und <code>RUNNING</code>.</li>\n<li><strong>OS Counter</strong>: 16-Bit-Zähler (Wertebereich bis 65535 mit Überlauf auf 0, 1, 2, ...).</li>\n<li><strong>API-Dienste</strong>:</li>\n<li><code>StartScheduleTableAbs(Tbl, 2)</code>: Absoluter Startaufruf bezogen auf Zählerstand 2.</li>\n<li><code>StartScheduleTableRel(Tbl, 2)</code>: Relativer Startaufruf mit einem zusätzlichen Offset von 2 Ticks ab Aufrufzeitpunkt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Definition der Schedule Table (<code>Tbl</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Basistabelle startet bei Offset 0, erreicht <code>EP1</code> bei Tick 2, <code>EP2</code> bei Tick 5, <code>EP3</code> bei Tick 8 und schließt den Durchlauf nach dem <code>Final Delay = 2</code> bei Offset 10 (Tick 0 der Folgewiederholung) ab.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Absoluter Start (<code>StartScheduleTableAbs(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt, während der OS Counter auf Stand 65535 steht. Der Zustand wechselt sofort von <code>STOPPED</code> nach <code>RUNNING</code>.</li>\n<li>Der initiale Verfallspunkt (<code>EP1</code>) wird bei Zählerstand <code>Counter = Startwert + Initial Offset = 2 + 2 = 4</code> abgearbeitet.</li>\n<li>Der Tabellenoffset 0 wird synchron zum absoluten Startwert 2 des OS Counters ausgerichtet. Entsprechend fallen <code>EP1</code> auf OS Counter 4, <code>EP2</code> auf OS Counter 7 und <code>EP3</code> auf OS Counter 10.</li>\n<li>Nach Erreichen von OS Counter 12 (Tabellendauer 10 Ticks) wiederholt sich die Tabelle periodisch: nächster Zyklus beginnt bei OS Counter 12, Folgedurchläufe schalten <code>EP1</code> bei 14, <code>EP2</code> bei 17, <code>EP3</code> bei 20 usw.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Relativer Start (<code>StartScheduleTableRel(Tbl, 2)</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Aufruf erfolgt ebenfalls bei OS Counter 65535, wodurch der Zustand von <code>STOPPED</code> nach <code>RUNNING</code> wechselt.</li>\n<li>Der Tabellennullpunkt wird relativ um das übergebene Offset (2 Ticks) verschoben: Tabellenoffset 0 liegt bei OS Counter <code>65535 + 2 = 1</code>.</li>\n<li>Entsprechend wird der initiale Verfallspunkt <code>EP1</code> bei OS Counter <code>1 + Initial Offset (2) = 3</code> erreicht.</li>\n<li>Nachfolgende Expiry Points liegen bei OS Counter 6 (<code>EP2</code>), 9 (<code>EP3</code>) und Tabellenende bei OS Counter 11.</li>\n<li>Die Folgeiteration startet bei OS Counter 11 mit <code>EP1</code> bei 13, <code>EP2</code> bei 16, <code>EP3</code> bei 19 etc.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Der API-Aufruf <code>StartScheduleTableAbs(ScheduleTableID, Start)</code> setzt den Zustand synchron auf <code>RUNNING</code>, wobei der absolute Startwert als Referenzbasis dient.</li>\n<li>Bei <code>StartScheduleTableRel(ScheduleTableID, Offset)</code> wird die Startzeit relativ zum aktuellen Zählerstand um den Parameter <code>Offset</code> in die Zukunft verschoben.</li>\n<li>In beiden Fällen wird der erste Verfallspunkt erst nach Ablauf des in der Schedule Table konfigurierten <code>Initial Offset</code> relativ zum Aktivierungszeitpunkt der Tabelle ausgeführt.</li>\n<li>Das Diagramm demonstriert die zyklische Wiederholung periodischer Schedule Tables nach Ablauf der Gesamtdauer (<code>Duration = Summe aller Delays inkl. Final Delay</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-5c2346d903f4f65e", "to": "FIG-1d02e8279b6a366f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1d02e8279b6a366f", "to": "FIG-5f12181a416d74b7", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5f12181a416d74b7", "to": "FIG-5cd76ae2c246879d", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5cd76ae2c246879d", "to": "FIG-da4bd3ddc9859e11", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
